-- Email-sync trigger function: same body, re-created so it is explicit that it targets public.users.id (uuid = auth.users.id).
CREATE OR REPLACE FUNCTION public.sync_user_email_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
  UPDATE public.users
  SET email = NEW.email,
      updated_at = CURRENT_TIMESTAMP
  WHERE id = NEW.id;
  RETURN NEW;
END;
$function$;

-- ---------------------------------------------------------------------------
-- Prisma contract bookkeeping, mirroring what `prisma db update` writes
-- (captured from a real `prisma db update` run on the local prod-like copy).
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS prisma_contract.contract (
    core_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    contract_json jsonb NOT NULL,
    CONSTRAINT contract_pkey PRIMARY KEY (core_hash)
);
CREATE TABLE IF NOT EXISTS prisma_contract.ledger (
    id bigserial NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    space text NOT NULL,
    migration_name text NOT NULL,
    migration_hash text NOT NULL,
    origin_core_hash text,
    origin_profile_hash text,
    destination_core_hash text NOT NULL,
    destination_profile_hash text,
    operations jsonb NOT NULL,
    CONSTRAINT ledger_pkey PRIMARY KEY (id)
);
